const MOVEMENT_FALLBACK={"version":1,"items":[{"url":"https://www.reddit.com/r/antisecretionist/comments/1y6f7wi/when_you_say_im_an_antisecretionist_what_do_you/","title":"When you say \u201cI\u2019m an anti-secretionist,\u201d what do you wish a restaurant understood?","source":"u/antisecretionist in r/antisecretionist","published":"2026-11-26","kind":"reddit","origin":"community","summary":"Our community asks what families wish they could say in one sentence when ordering bread, steak or another favorite dish."}]};
const movementFeedUrl = 'https://raw.githubusercontent.com/christopherjeromehayman/antisecretionism/main/web/movement-links.json';
const movementPlatforms = new Map([
  ['news', 'News'], ['reddit', 'Reddit'], ['facebook', 'Facebook'],
  ['instagram', 'Instagram'], ['business', 'Business website']
]);
const movementOrigins = ['community', 'business', 'independent'];
const movementDateFormat = new Intl.DateTimeFormat('en-US', {
  month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC'
});
let recentMovementItems;
let nextMovementCheck = 0;

function movementText(value, limit) {
  if (typeof value !== 'string' || value.length > limit) return '';
  return value.trim();
}

function movementItems(feed) {
  if (feed?.version !== 1 || !Array.isArray(feed.items)) {
    throw new Error('Invalid movement feed');
  }
  const items = [];
  const seen = new Set();
  for (const entry of feed.items) {
    if (!entry || !movementOrigins.includes(entry.origin) || !movementPlatforms.has(entry.kind)) continue;
    const title = movementText(entry.title, 320);
    const source = movementText(entry.source, 160);
    const published = movementText(entry.published, 10);
    if (!title || !source || !/^\d{4}-\d{2}-\d{2}$/.test(published)) continue;
    const date = new Date(published + 'T00:00:00Z');
    if (!Number.isFinite(date.getTime()) || date.toISOString().slice(0, 10) !== published) continue;
    let link;
    try { link = new URL(movementText(entry.url, 2000)); } catch { continue; }
    if (link.protocol !== 'https:' || link.username || link.password || link.port) continue;
    link.hash = '';
    for (const key of [...link.searchParams.keys()]) {
      if (/^(utm_|fbclid$|igsh$)/i.test(key)) link.searchParams.delete(key);
    }
    link.searchParams.sort();
    const key = link.href.replace(/\/$/, '');
    if (seen.has(key)) continue;
    seen.add(key);
    items.push({ title, source, published, url: link.href, date,
      kind: entry.kind, origin: entry.origin, summary: movementText(entry.summary, 600) });
  }
  if (feed.items.length && !items.length) throw new Error('No valid movement items');
  return items.sort((a, b) => b.date - a.date);
}

async function loadMovementItems() {
  if (Date.now() < nextMovementCheck) return recentMovementItems;
  const abort = new AbortController();
  const timeout = setTimeout(() => abort.abort(), 1600);
  try {
    const response = await fetch(movementFeedUrl, {
      signal: abort.signal, redirect: 'error', headers: { Accept: 'application/json' }
    });
    if (!response.ok) throw new Error('Movement feed unavailable');
    const limit = 8 * 1024 * 1024;
    if (Number(response.headers.get('content-length')) > limit) throw new Error('Movement feed too large');
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let size = 0;
    let data = '';
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > limit) {
        abort.abort();
        throw new Error('Movement feed too large');
      }
      data += decoder.decode(value, { stream: true });
    }
    recentMovementItems = movementItems(JSON.parse(data + decoder.decode()));
    nextMovementCheck = Date.now() + 5 * 60_000;
  } catch {
    recentMovementItems ??= movementItems(MOVEMENT_FALLBACK);
    nextMovementCheck = Date.now() + 60_000;
  } finally {
    clearTimeout(timeout);
  }
  return recentMovementItems;
}

function movementHtml(text) {
  const entities = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return text.replace(/[&<>"']/g, char => entities[char]);
}

function movementList(items) {
  return '<ul class="coverage-items">' + items.map(item => {
    const heading = '<h3 class="coverage-title"><a href="' + movementHtml(item.url) + '">' + movementHtml(item.title) + '</a></h3>';
    const credit = movementHtml(item.source) + ' · ' + movementPlatforms.get(item.kind);
    const date = '<time datetime="' + item.published + '">' + movementDateFormat.format(item.date) + '</time>';
    const summary = item.summary ? '<p>' + movementHtml(item.summary) + '</p>' : '';
    return '<li>' + heading + '<p class="source-line">' + credit + ' · ' + date + '</p>' + summary + '</li>';
  }).join('') + '</ul>';
}

async function renderMovementPage(bytes) {
  const items = await loadMovementItems();
  const groups = [
    ['community', 'From our community', 'Our own posts and conversations will appear here.'],
    ['business', 'On the menu', 'We’ll link to restaurants and food makers here when we can verify the Gemmy badge or a No Secretions label on their own menu, website or public post.'],
    ['independent', 'Elsewhere in the news and on social', 'We haven’t listed an independent mention yet. This is where you’ll find reporting and public posts from people outside our team.']
  ];
  const sections = groups.map(([origin, heading, empty]) => {
    const matching = items.filter(item => item.origin === origin);
    const content = matching.length ? movementList(matching.slice(0, 20)) : '<p>' + empty + '</p>';
    const badge = origin === 'business' ? '<p><a href="/menu-label">Put Gemmy on your menu</a></p>' : '';
    return '<section class="coverage-group" aria-labelledby="mentions-' + origin + '"><h2 id="mentions-' + origin + '">' + heading + '</h2>' + content + badge + '</section>';
  });
  const template = new TextDecoder().decode(bytes);
  return new TextEncoder().encode(template.replace('<!-- movement-links -->', () => sections.join('\n')));
}

const petitionChoice = 'petition-platform-label';
const petitionReceipt = 'petition-browser-receipt';
const options = new Set([petitionChoice,'hat','shirt','stickers','grocer','brand']);
const reachEvents = [
  'intro_view', 'share_link_copied', 'share_sheet_completed',
  'badge_code_copied', 'badge_referral', 'share_referral'
];
const json=(data,status=200)=>Response.json(data,{status,headers:{'cache-control':'no-store'}});
function publisher(env){return /^pub-\d{16}$/.test(env.ADSENSE_PUBLISHER||'')?env.ADSENSE_PUBLISHER:null}
const legacyBrandRoutes = new Map([
  ['/maple', '/gemmy'],
  ['/maple.html', '/gemmy'],
  ['/assets/maple-scout.png', '/assets/gemmy.png'],
  ['/assets/maple-mark.png', '/assets/gemmy-mark.png'],
  ['/assets/maple.webp', '/assets/gemmy.png'],
  ['/assets/mark.svg', '/assets/gemmy-mark.png'],
  ['/favicon.ico', '/assets/gemmy-mark.png']
]);
// A receipt lets the same browser recognize a signature made while signed in.
function petitionBrowser(req) {
  const id = req.headers.get('X-Petition-Browser');
  return /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id || '')
    ? 'petition-browser:' + id.toLowerCase() : null;
}

async function recordPetition(db, account, browser) {
  const signer = account || browser;
  const signature = db.prepare(
    'INSERT OR IGNORE INTO support(visitor, choice) SELECT ?, ? WHERE NOT EXISTS ' +
    '(SELECT 1 FROM support WHERE visitor IN (?, ?) AND choice IN (?, ?))'
  ).bind(signer, petitionChoice, account, browser, petitionChoice, petitionReceipt);
  if (account && browser) {
    const receipt = db.prepare('INSERT OR IGNORE INTO support(visitor, choice) VALUES (?, ?)')
      .bind(browser, petitionReceipt);
    await db.batch([signature, receipt]);
  } else {
    await signature.run();
  }
}

async function supportState(db, account, browser) {
  const count = db.prepare('SELECT COUNT(*) AS total FROM support WHERE choice = ?').bind(petitionChoice);
  const choices = db.prepare(
    'SELECT choice FROM support WHERE visitor = ? AND choice != ? ' +
    'UNION SELECT ? WHERE EXISTS ' +
    '(SELECT 1 FROM support WHERE visitor = ? AND choice IN (?, ?))'
  ).bind(account, petitionReceipt, petitionChoice, browser, petitionChoice, petitionReceipt);
  const [totals, selected] = await db.batch([count, choices]);
  return { total: totals.results[0].total, signedIn: Boolean(account), choices: selected.results.map(row => row.choice) };
}

async function reachMetrics(req, db, origin) {
  if (req.method === 'GET') {
    const { results } = await db.prepare(
      'SELECT event, SUM(total) AS total FROM reach_daily GROUP BY event'
    ).all();
    const counts = Object.fromEntries(reachEvents.map(event => [event, 0]));
    for (const row of results) counts[row.event] = row.total;
    return json({ counts, asOf: new Date().toISOString() });
  }
  if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405);
  if (req.headers.get('Origin') !== origin) return json({ error: 'Invalid origin' }, 403);
  if (req.headers.get('Content-Type')?.split(';')[0].trim().toLowerCase() !== 'application/json') {
    return json({ error: 'Use application/json' }, 415);
  }

  // These messages contain just one of the event names above.
  let body = '';
  const decoder = new TextDecoder();
  let size = 0;
  if (req.body) {
    for await (const chunk of req.body) {
      size += chunk.byteLength;
      if (size > 128) return json({ error: 'Event message is too large' }, 413);
      body += decoder.decode(chunk, { stream: true });
    }
  }
  let event;
  try {
    const payload = JSON.parse(body + decoder.decode());
    if (payload && Object.keys(payload).length === 1) event = payload.event;
  } catch { /* A malformed message is handled as an unknown event below. */ }
  if (!reachEvents.includes(event)) return json({ error: 'Invalid event' }, 400);

  if (req.headers.get('Sec-GPC') === '1' || req.headers.get('DNT') === '1') {
    return new Response(null, { status: 204, headers: { 'Cache-Control': 'no-store' } });
  }
  await db.prepare(
    "INSERT INTO reach_daily(day, event, total) VALUES (date('now'), ?, 1) " +
    'ON CONFLICT(day, event) DO UPDATE SET total = total + 1'
  ).bind(event).run();
  return new Response(null, { status: 204, headers: { 'Cache-Control': 'no-store' } });
}
export default {
 async fetch(req,env){
  const url=new URL(req.url), path=url.pathname;
  const domain = 'https://antisecretionist.com';
  const platform = 'https://anti-secretarian.drinktobasco.chatgpt.site';
  const platformRequest = url.origin === platform;
  if (['GET','HEAD'].includes(req.method) && !path.startsWith('/api/') &&
      (url.hostname === 'www.antisecretionist.com' || (platformRequest && env.CUSTOM_DOMAIN_LIVE === 'yes'))) {
    return Response.redirect(domain + path + url.search, 301);
  }
  if (path === '/api/reach') {
    try {
      return await reachMetrics(req, env.DB, url.origin);
    } catch {
      return json({ error: 'Activity counts are temporarily unavailable' }, 503);
    }
  }
  if(path==='/api/milk-poll'){
    const kinds=['coconut','oat','soy','almond','pea','rice','other'];
    const visitor=req.headers.get('oai-authenticated-user-id');
    try{
      if(req.method==='POST'){
        if(req.headers.get('origin')!==url.origin)return json({error:'Invalid origin'},403);
        if(!visitor)return json({error:'Sign in first'},401);
        const body=await req.json().catch(()=>null);
        if(!kinds.includes(body?.kind))return json({error:'Unknown milk'},400);
        await env.DB.batch([
          env.DB.prepare("DELETE FROM support WHERE visitor=? AND choice GLOB 'milk-*'").bind(visitor),
          env.DB.prepare('INSERT INTO support(visitor,choice) VALUES (?,?)').bind(visitor,'milk-'+body.kind)
        ]);
      }else if(req.method!=='GET')return json({error:'Method not allowed'},405);
      const rows=await env.DB.prepare("SELECT substr(choice,6) AS kind, COUNT(*) AS votes FROM support WHERE choice GLOB 'milk-*' GROUP BY choice").all();
      const own=visitor?await env.DB.prepare("SELECT substr(choice,6) AS kind FROM support WHERE visitor=? AND choice GLOB 'milk-*'").bind(visitor).first():null;
      return json({signedIn:Boolean(visitor),mine:own?.kind??null,counts:Object.fromEntries(rows.results.map(row=>[row.kind,row.votes]))});
    }catch{return json({error:'Voting is temporarily unavailable'},503)}
  }
  if (path === '/api/support') {
    const account = req.headers.get('oai-authenticated-user-id');
    const browser = petitionBrowser(req);
    try {
      if (req.method === 'POST') {
        if (req.headers.get('origin') !== url.origin) return json({error:'Invalid origin'}, 403);
        const payload = await req.json().catch(() => null);
        const choice = payload?.choice;
        if (!options.has(choice)) return json({error:'Unknown choice'}, 400);
        if (choice === petitionChoice) {
          if (!account && !browser) return json({error:'Refresh the petition and try again.'}, 400);
          await recordPetition(env.DB, account, browser);
        } else {
          if (!account) return json({error:'Sign in first'}, 401);
          await env.DB.prepare('INSERT OR IGNORE INTO support(visitor,choice) VALUES (?,?)').bind(account,choice).run();
        }
      } else if (req.method !== 'GET') {
        return json({error:'Method not allowed'}, 405);
      }
      return json(await supportState(env.DB, account, browser));
    } catch {
      return json({error:'The signup service is temporarily unavailable. Please try again.'}, 503);
    }
  }
  if(!['GET','HEAD'].includes(req.method))return new Response(null,{status:405});
  const brandRedirect = legacyBrandRoutes.get(path);
  if (brandRedirect) return Response.redirect(url.origin + brandRedirect + url.search, 301);
  const pub=publisher(env);
  if(path==='/ads.txt'&&pub)return new Response('google.com, '+pub+', DIRECT, f08c47fec0942fa0\n',{headers:{'content-type':'text/plain'}});
  const asset=ASSETS[path==='/'?'/index.html':path];
  if(!asset)return new Response('Page not found',{status:404});
  const [type,b64]=asset;
  let bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));
  if (path === '/movement' || path === '/movement.html') bytes = await renderMovementPage(bytes);
  if (platformRequest && (type.startsWith('text/html') || path === '/sitemap.xml' || path === '/robots.txt')) {
    const page = new TextDecoder().decode(bytes).replaceAll(domain, platform);
    bytes = new TextEncoder().encode(page);
  }
  if(type.startsWith('text/html')&&pub){
    let tags='<meta name="google-adsense-account" content="ca-'+pub+'">';
    if(env.ADS_APPROVED==='yes'&&['/pantry','/pizza','/los-gatos','/beyond'].includes(path))tags+='<script async crossorigin="anonymous" src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-'+pub+'"></script>';
    bytes=new TextEncoder().encode(new TextDecoder().decode(bytes).replace('</head>',tags+'</head>'));
  }
  return new Response(req.method==='HEAD'?null:bytes,{headers:{'content-type':type,'x-content-type-options':'nosniff'}});
 }
};
